<?php namespace App\Http\Requests; use Illuminate\Foundation\Http\FormRequest; class SaveFoodItemRequest extends FormRequest { public function authorize(): bool { return $this->user()?->role === 'vendor'; } public function rules(): array { return ['category_id' => ['required', 'exists:categories,id'], 'name' => ['required', 'string', 'max:255'], 'description' => ['nullable', 'string', 'max:1000'], 'price' => ['required', 'numeric', 'min:0.50', 'max:999.99'], 'availability' => ['required', 'boolean']]; } }